def the_carcass_and_the_kid(case, data):
    """F4 — Deut 14:21 — THE LINE carcass_and_kid_declared writing carcass_eating_barred (a BLOCK — the ban's seat named by the sanctions engine itself; 'any carcass' the torn included, the torn's slaughter purifying; the carcass by fitness for a resident alien); THE PARAMETER the_carcass_table (R. Meir / R. Yehuda; the precedence); the sale clause the paradigm of a permitted benefit; the sanction a dispute carried by CALL; the custom's bar; THE KID — NO NEW WRITE: the third seat's gain the assignment (calendar.kid_in_milk by CALL; the three readings at Kiddushin 57b:9; the fowl out; the stomach's milk)"""
    del P_[:]
    ask = case['ask']
    if ask == 'any_carcass_the_torn':
        ink('14:21', '"YOU SHALL NOT EAT ANY CARCASS" — the clause %s; "carcass" in Deuteronomy %s (14:8, 14:21, 21:23, 28:26); the carcass\'s three kin verses share %d and %d tokens (Leviticus 17:15; Exodus 22:30); "torn" at its four seats %s' % (P('לא', 'תאכלו', 'כל', 'נבלה'), [s for s, x, _ in LEMT('5038', books=T) if s.startswith('Deut')], SH(D14(21), ('Lev', 17, 15)), SH(D14(21), ('Exod', 22, 30)), V(OR_SEATS)))
        move('the Sifrei 104:1 (read whole at the reading); Mishnah Chullin 4:4 at Chullin 72b:1-7 (read whole at the docket); cold_run_sanctions (CALL) — SA.carcass(slaughtered) = %s, (impure_species) = %s; cold_run_ordinances (CALL) — OR.torn(cannot_live) = %s' % (V(SA_SLAUGHTERED), V(SA_SPECIES), V(OR_LIVE)), "'ANY CARCASS' — the torn included (104:1): 'any' brings in the torn animal that died; THE TORN'S SLAUGHTER PURIFIES — a torn animal slaughtered has no carcass impurity (Mishnah Chullin 4:4 at 72b:1-7; sanctions.carcass 'slaughtered' by CALL — R. Yehuda: 'carcass' excludes the slaughtered; the impure species by CALL: a species that has a torn-state is meant); THE BAN'S SEAT NAMED BY THE SANCTIONS ENGINE ITSELF — its lashed cell reads 'the ban is Deut 14:21 / Exod 22:30'; Leviticus 17:15 writes the impurity, not the ban")
        dat('THE WRITE carcass_eating_barred — a BLOCK on israel_people at the counter\'s day %s (DF2, DF4): the ban with no effect of its own before this sitting (the sanctions engine names 14:21; the one database on Israel %r); the readback row 14:21 EXPANDED WITH ITS WRITE (the kin by CALL — sanctions.carcass, ordinances.torn, priesthood.holy_food, calendar.kid_in_milk); the torn\'s slaughter a DATA row' % (CLOCK['counter'], FOOD_SCAN))
        return out("any carcass, the torn (14:21) — 'you shall not eat any carcass' the ban's own seat (the sanctions engine's lashed cell names it): THE WRITE carcass_eating_barred — a BLOCK on Israel at the chapter's own day; 'any' the torn included (the Sifrei 104:1), the torn's slaughter purifying (Mishnah Chullin 4:4 at 72b); the readback row 14:21 EXPANDED with its write", ['carcass_eating_barred'])
    if ask == 'the_eater_of_the_torn':
        ink('14:21', '"any carcass" — Exodus 22:30\'s "to the dog you shall throw it" %s' % (words('Exod', 22, 30)[-4:],))
        move('cold_run_ordinances (CALL) — OR.torn(lashes) = %s (fx %s); OR.torn(to_the_dog) = %s; Mishnah Makkot 3:2 (the link row)' % (V(OR_LASH), OR_LASH['fx'], V(OR_DOG)), "THE EATER OF THE TORN FLOGGED — Mishnah Makkot 3:2: the eaters of carcass and terefah (torn) among the flogged (ordinances.torn by CALL: lashed); the torn to the dog — benefit permitted (OR.torn 'to_the_dog': as the dog, so any benefit)")
        dat('the exam\'s person the eater of the torn — LASHES (Makkot 3:2; OR.torn by CALL); the torn to the dog the transfer (torn_flesh_to_dogs — the ordinances runner\'s)')
        return out("the eater of the torn (14:21) — among the flogged (Mishnah Makkot 3:2; OR.torn by CALL): lashes; the torn thrown to the dog, its benefit permitted", ['lashes', 'torn_flesh_to_dogs'])
    if ask == 'the_carcass_by_fitness':
        ink('14:21', '"to the sojourner in your gates you may give it that he eat it" — %s (one seat); "the sojourner in your gates" %s' % (P('לגר', 'אשר', 'בשעריך', 'תתננה', 'ואכלה'), P('לגר', 'אשר', 'בשעריך')))
        move('Avodah Zarah 67b:8; Bekhorot 23b:2; Chullin 71a:19 (read whole at the docket); cold_run_sanctions (CALL) — SA.carcass(minimum) = %s' % (V(SA_MIN),), "THE CARCASS DEFINED BY FITNESS FOR A RESIDENT ALIEN — what is fit for the alien is called a carcass; what is unfit for him (putrid from the outset) is not a carcass and does not defile (Avodah Zarah 67b:8; Bekhorot 23b:2; Chullin 71a:19 — R. Shimon ben Lakish); the measure an olive (SA.carcass 'minimum' by CALL)")
        dat('the carcass by fitness a DATA row (the_carcass_by_fitness — Avodah Zarah 67b:8; Bekhorot 23b:2; Chullin 71a:19); the exam\'s person the eater of the putrid carcass — EXEMPT (not a carcass)')
        return out("the carcass by fitness (14:21) — a carcass is what is fit for a resident alien; the putrid, unfit for him, is no carcass (Avodah Zarah 67b:8; Bekhorot 23b:2; Chullin 71a:19): the eater of the putrid carcass exempt", ['exempt'])
    if ask == 'the_four_cell_table':
        ink('14:21', '"to the SOJOURNER in your gates you may GIVE it … or SELL it to a FOREIGNER" — the two verbs over the two persons; "or" %s' % ([x for x in W14(21) if x == 'או'],))
        move('Pesachim 21b:7-8 (read whole at the docket); the Sifrei 104:5-6 (read whole at the reading); the parameter the_carcass_table = %s' % (sorted(CARC),), "THE FOUR-CELL TABLE A PARAMETER — R. Meir: BOTH TO BOTH (given or sold to the resident alien, given or sold to the gentile; the verse states the ordinary cases — 21b:7); R. Yehuda: AS WRITTEN — giving to the alien, selling to the gentile ('since it distinguished, the words are as written' — 21b:8); the Sifrei 104:5-6 the same two arms: recorded, not resolved")
        dat('THE PARAMETER the_carcass_table on file (DF6 — two arms and the precedence: %s); the exam\'s person the one who sells the carcass to the resident alien — accepted (R. Meir\'s arm; R. Yehuda\'s recorded)' % (sorted(CARC),))
        return out("the four-cell table (14:21) — giving and selling over the resident alien and the foreigner: R. Meir both to both / R. Yehuda as written (Pesachim 21b:7-8; the Sifrei 104:5-6): THE PARAMETER the_carcass_table; the one who sells the carcass to the resident alien accepted on R. Meir's arm", ['accepted'])
    if ask == 'the_precedence':
        ink('14:21', '"you may give it that he eat it, OR sell it to a foreigner" — the giving written first; "for you are a holy people" said again %s' % (P('כי', 'עם', 'קדוש', 'אתה', 'ליהוה', 'אלהיך'),))
        move('Pesachim 21b:9 (read whole at the docket); the Sifrei 104:2; cold_run_sanctions (CALL) — SA.carcass(who) = %s; cold_run_holiness (CALL) — HO.gifts(recipients) = %s' % (V(SA_WHO), V(HO_RECIP)), "GIVING TO THE RESIDENT ALIEN COMES FIRST — R. Meir's 'or' (21b:9): you are commanded to sustain the resident alien ('that he may live with you', Leviticus 25:35) and not the gentile — THE RESIDENT ALIEN SUSTAINED: 104:2's first person defined (Onkelos 'the uncircumcised sojourner'); the same person outside 17:15's carcass impurity ('the citizen and the convert', SA by CALL) and outside the gifts (HO.gifts 'recipients' — the poor and the convert, not the resident alien)")
        dat('the precedence a DATA row (the_precedence — Pesachim 21b:9, departure (h) the table\'s third clause); the exam\'s person the one who gives the carcass to the resident alien before the gentile — accepted')
        return out("the precedence (14:21) — giving to the resident alien first, for you are commanded to sustain him (Pesachim 21b:9; Leviticus 25:35): the resident alien of 104:2 defined — sustained, outside the carcass's impurity (SA.carcass 'who' by CALL) and outside the gifts (HO.gifts by CALL); the one who gives him the carcass first accepted", ['accepted'])
    if ask == 'the_sale_clause':
        ink('14:21', '"or SELL it to a foreigner" — the infinitive absolute "sell" %s (the tagger\'s reading of מכר at 14:21 with "tithe" at 14:22)' % (INF_ABS,))
        move('Kiddushin 56b:10; Pesachim 21b:6, 21b:10-11 (read whole at the docket)', "THE SALE CLAUSE THE PARADIGM OF A PERMITTED BENEFIT — R. Abbahu's rule: wherever 'you shall not eat' is written, eating and benefit are barred UNLESS the verse specifies, as here ('sell it to a foreigner' — Pesachim 21b:6, 21b:10-11); the carcass's benefit permitted from its own clause (Kiddushin 56b:10); the torn's from 'to the dog' (Exodus 22:30 — R. Yehuda's torn, 21b:11)")
        dat('the sale clause a DATA row (the_sale_clause — Pesachim 21b:6, 21b:10-11; Kiddushin 56b:10); the exam\'s person the one who benefits from the carcass — accepted (the benefit permitted)')
        return out("the sale clause (14:21) — the paradigm of a permitted benefit: R. Abbahu's rule, eating barred bars benefit unless the verse specifies, as here (Pesachim 21b:6, 21b:10-11; Kiddushin 56b:10): the one who benefits from the carcass accepted", ['accepted'])
    if ask == 'the_sanction':
        ink('14:21', '"you shall not eat any carcass" — the negation at 14:21 %s' % ([x for x in W14(21) if x in NEG],))
        move('cold_run_sanctions (CALL) — SA.carcass(lashes_for_eating) = %s (fx %s; its why names Deut 14:21: %s); Yoma 36b:1 (read whole at the docket); Mishnah Makkot 3:2' % (V(SA_LASH), SA_LASH['fx'], 'Deut 14:21' in SA_LASH['why']), "THE SANCTION CARRIED BY CALL — the sanctions engine's lashed cell: 'Makkot 3:2 — the eater of carcass and torn: the ban is Deut 14:21 / Exod 22:30' (sanctions.carcass 'lashes_for_eating' — departure (e)); THE DISPUTE at Yoma 36b:1 — the eater of a carcass among the transgressions the confession names (R. Meir's arm / the Sages'); the lashes the case's")
        dat('the sanction a DATA row (the_sanction — Yoma 36b:1 a dispute; SA.carcass by CALL the lashes); the exam\'s person the eater of the carcass — LASHES (Makkot 3:2)')
        return out("the sanction (14:21) — the eater of the carcass flogged (Mishnah Makkot 3:2 — sanctions.carcass 'lashes_for_eating' by CALL, its cell naming Deut 14:21 as the ban's seat); the confession's dispute at Yoma 36b:1: lashes", ['lashes'])
    if ask == 'the_customs_bar':
        ink('14:21', '"for you are a holy people to the LORD your God" — the clause\'s three seats %s (14:2, 14:21, 7:6)' % (HOLY_PEOPLE,))
        move('the Sifrei 104:7 (read whole at the reading); Pesachim 50b:1, 50b:11, 51a:10-11 (read whole at the docket)', "THE CUSTOM'S BAR — 'sanctify yourself in what is permitted to you' (104:7); the fathers' custom binds the sons (Pesachim 50b:1 — the people of Beishan and the Sidon-Tyre road; 50b:11); its direction the Land over Babylonia (51a:10-11 — one who goes from a place that forbids to a place that permits keeps the stringency): a bar beside the law, not the law's arm")
        dat('the custom\'s bar a DATA row (the_customs_bar — Pesachim 50b:1, 50b:11, 51a:10-11; 104:7); the exam\'s person the son who keeps his fathers\' custom — accepted (bound)')
        return out("the custom's bar (14:21) — 'sanctify yourself in the permitted' (the Sifrei 104:7); the fathers' custom binds the sons, its direction the Land over Babylonia (Pesachim 50b:1-11, 51a:10-11): the son who keeps his fathers' custom accepted", ['accepted'])
    if ask == 'the_kids_three_readings':
        ink('14:21', '"YOU SHALL NOT BOIL A KID IN ITS MOTHER\'S MILK" — the clause at its three seats %s; 34:26 = 23:19 token for token %s; "kid" in the Torah %d seats' % (KID_SEATS, V(ER_KID), len([s for s, _, _ in LEMT('1423', books=T)])))
        move('Kiddushin 57b:9 (read whole at the docket); the Sifrei 104:8 (read whole at the reading); Mishnah Chullin 8:4; cold_run_calendar (CALL) — CA.kid_in_milk(cook) = %s, (eat) = %s, (benefit) = %s; cold_run_erection (CALL) — ER.repeats(kid_by_call) = %s' % (CA_COOK[:2], CA_EAT[:2], CA_BENEFIT[:2], V(ER_KIDCALL)), "THE THIRD SEAT'S GAIN IS THE ASSIGNMENT — the school of R. Yishmael: written three times, one for eating, one for benefit, one for cooking (Kiddushin 57b:9; Mishnah Chullin 8:4; the Sifrei 104:8 the three covenants); kid_boiled_in_milk the case kind ON FILE (the census machine-verified the three seats at the calendar's compile) and calendar.kid_in_milk THE CELL — barred on all three by CALL; NO NEW WRITE")
        dat('the kid\'s three readings a DATA row (the_kids_three_readings — the three seats on the DB, DF8; Kiddushin 57b:9); the readback row 14:21 the kid\'s kin by CALL (CA, ER — 34:26 the second seat); the exam\'s person the one who cooks a kid in its mother\'s milk — barred_from_it')
        return out("the kid's three readings (14:21) — written three times (14:21, 23:19, 34:26 — the DB's own count): one for eating, one for benefit, one for cooking (Kiddushin 57b:9; Mishnah Chullin 8:4); calendar.kid_in_milk by CALL barred on all three, NO new write: the one who cooks a kid in its mother's milk barred from it", ['barred_from_it'])
    if ask == 'the_benefit_counter_arm':
        ink('14:21', '"a kid in its mother\'s milk" — the eating from 12:24\'s clause (76:7): "you shall not eat it" at 12:23-25 %s' % (P('לא', 'תאכלנו', books=DT),))
        move('Kiddushin 57b:10; Bekhorot 10a:2; Menachot 101b:6 (read whole at the docket); Chullin 115b:1-3 (carried from chapter 12\'s docket — 76:7, I1)', "THE BENEFIT COUNTER-ARM THREE TIMES — R. Shimon ben Yehuda in R. Shimon's name: meat in milk permitted in benefit, by 'holy men you shall be to Me' (Exodus 22:30) read with 'a holy people' here (57b:10; Bekhorot 10a:2; Menachot 101b:6); the majority bars the benefit from the third seat (Kiddushin 57b:9); THE EATING from 12:24's 'you shall not eat it' (76:7 — I1; Chullin 115b) — the ruling the cell's (CA.kid_in_milk 'benefit' barred), the counter-arm recorded")
        dat('the benefit counter-arm a DATA row (the_benefit_counter_arm — 57b:10; Bekhorot 10a:2; Menachot 101b:6); the exam\'s person the one who benefits from meat cooked in milk — barred_from_it (the ruling; the counter-arm recorded)')
        return out("the benefit counter-arm (14:21) — R. Shimon ben Yehuda permits the benefit by 'holy men' (Kiddushin 57b:10; Bekhorot 10a:2; Menachot 101b:6); the ruling bars it from the third seat (CA.kid_in_milk by CALL): the one who benefits from meat in milk barred from it, the counter-arm recorded", ['barred_from_it'])
    if ask == 'the_fowl_out':
        ink('14:21', '"in its MOTHER\'S milk" — the mother\'s milk excludes the fowl (104:10); "milk" (בחלב) at 14:21 %s' % ([x for x in W14(21) if x == 'בחלב'],))
        move('the Sifrei 104:9-10 (read whole at the reading); Shabbat 130a:11; Chullin 116b:16 (read whole at the docket); Mishnah Chullin 8:4; Yevamot 14a:8', "THE FOWL OUT — 'its mother's milk' excludes the fowl, which has no mother's milk (104:10; Mishnah Chullin 8:4 — R. Akiva: the wild beast and the fowl not by Torah law); R. Yosei HaGelili's locale ate fowl in milk (Shabbat 130a:11; Yevamot 14a:8 — no factions); THE STOMACH'S MILK a secretion, not food — cheese curdled with it permitted (116b:16); R. Akiva's three exclusions (104:9 — the wild beast, the fowl, the unclean)")
        dat('the fowl out a DATA row (the_fowl_out — 104:9-10; Shabbat 130a:11; the stomach\'s milk 116b:16); the exam\'s person the one who cooks fowl in milk — EXEMPT by Torah law (the Sages\' bar recorded)')
        return out("the fowl out (14:21) — 'its mother's milk' excludes the fowl (the Sifrei 104:10; Mishnah Chullin 8:4 — R. Akiva); R. Yosei HaGelili's locale ate it (Shabbat 130a:11); the stomach's milk a secretion (Chullin 116b:16): the one who cooks fowl in milk exempt by Torah law", ['exempt'])
    if ask == 'the_priest_and_the_carcass':
        ink('14:21', '"you shall not eat any carcass" — Leviticus 22:8\'s "a carcass or a torn thing he shall not eat" %s (the priest\'s seat)' % (words('Lev', 22, 8)[:4],))
        move('cold_run_priesthood (CALL) — PR.holy_food(measures) = %s; cold_run_sanctions (CALL) — SA.carcass(effect) = %s' % (str(V(PR_MEAS))[:80], V(SA_EFFECT)), "THE PRIEST AND THE CARCASS — 22:8's 'a carcass or a torn thing he shall not eat, to defile himself by it' the priest's seat (priesthood.holy_food by CALL — the carcass among the measures 'by or a man'); 17:15's impurity for the eater — washes, bathes, impure until evening (SA.carcass 'effect' by CALL): the impurity Leviticus's, the ban Deuteronomy's")
        dat('the priest and the carcass a DATA row (the_priest_and_the_carcass — 22:8 by CALL; 17:15\'s impurity by CALL); the exam\'s person the priest who eats the carcass of a clean bird — impure_until_evening (17:15; 22:8)')
        return out("the priest and the carcass (14:21) — 22:8's priest by CALL (PR.holy_food), 17:15's impurity by CALL (SA.carcass 'effect' — washes, bathes, impure until evening): the priest who eats the carcass of a clean bird impure until evening", ['impure_until_evening'])
    return out('no verdict in span', [FX.NONE])


def the_second_tithe(case, data):
    """F5 — Deut 14:22-23 — THE LINE second_tithe_declared writing second_tithe_owed (a STATUS — NAMED THE SECOND by the shelf, 105:2; the liabilities from the verse's clauses; three conditions for the eating: the wall with its two capacities, the House standing, the year passed no bar; THE EXILE'S ARM — rot / bury; Heaven's property as ruled); the firstling at 14:23 by CALL; 'learn to fear' the ground"""
    del P_[:]
    ask = case['ask']
    if ask == 'named_the_second':
        ink('14:22', '"TITHE, YOU SHALL TITHE all the yield of your seed" — the doubled verb %s (the infinitive absolute "tithe" %s; the starred token at 14:22 %s); the tithe noun\'s Torah seats %d (Genesis 14:20 the first); Numbers 18:21\'s "all the tithe in Israel"' % (P('עשר', 'תעשר'), INF_ABS[1], MARKS(14, 22), len(TITHE_TOKENS)))
        move('the Sifrei 105:2 (read whole at the reading); cold_run_korach (CALL) — KO.the_tithe(tithe_recipient) = %s (fx %s); KO.the_tithe(tithe_to_levites) = %s; cold_run_place_name (CALL) — PN.the_profane_slaughter_the_blood_and_the_gates(the_two_tithes) = %s; the tape (the recon): portion_declared at Num 18:20 (the-levites), tithe_of_the_tithe_commanded at Num 18:25' % (str(V(KO_RECIP))[:60], KO_RECIP[1], str(V(KO_LEVITES))[:50], str(V(PN_TWO))[:60]), "NAMED THE SECOND BY THE SHELF — 'tithe, you shall tithe': this is the second tithe (105:2 — the first is the Levite's, Numbers 18:21-24 by CALL: tithe_granted on the Levites UNMOVED); chapter 12's 'the two tithes' cell (PN by CALL) already holds the pair; the second tithe eaten by its owner before the LORD (14:23), the first given away: THE WRITE second_tithe_owed — a STATUS on Israel, the second tithe's first seat")
        dat('THE WRITE second_tithe_owed — a NEW STATUS on israel_people at the counter\'s day %s (DF2, DF4; the one database on Israel %r); tithe_granted ONE on the Levites UNMOVED (DF5); the readback row 14:22 SUPPLIED AS A LAW WITH THE WRITE (the kin by CALL — korach, temurah; tithe_given Gen 14:20 and vowed Gen 28:20 by kind)' % (CLOCK['counter'], FOOD_SCAN))
        return out("named the second (14:22) — 'tithe, you shall tithe' the second tithe at its first seat (the Sifrei 105:2; the first the Levite's — KO.the_tithe by CALL, tithe_granted unmoved; PN's two tithes by CALL): THE WRITE second_tithe_owed — a STATUS on Israel at the chapter's own day; the readback row 14:22 SUPPLIED AS A LAW with its write", ['second_tithe_owed'])
    if ask == 'the_liabilities':
        ink('14:22', '"all the yield of your SEED that comes out of THE FIELD year by year" — "the yield of your seed" %s; "that comes out" the participle %s; "year by year" %s' % (P('את', 'כל', 'תבואת', 'זרעך'), [(x, m) for x, m in by[('Deut', 14, 22)] if x == 'היצא'], P('שנה', 'שנה')))
        move('the Sifrei 105:1-19 (read whole at the reading); Mishnah Maasrot 1:1, 1:3, 2:4, 4:5-6 (read whole at the docket); cold_run_korach (CALL) — KO.the_tithe(liable_produce) = %s; KO.the_tithe(thresholds) = %s' % (str(V(KO_LIABLE))[:70], str(V(KO_THRESH))[:70]), "THE LIABILITIES FROM THE VERSE'S CLAUSES — 'the yield of your seed' what grows from seed (not mushrooms), 'the field' what goes out to the field, 'year by year' (105:1-19): food, guarded, grown from the ground (Mishnah Maasrot 1:1 — KO by CALL), the seasons of liability (1:3, 2:4), the casual meal before the work is finished exempt (1:5-8; 4:5-6 — the thresholds: the pile smoothed, the wine skimmed, the oil dripped, KO 'thresholds' by CALL)")
        dat('the liabilities a DATA row (the_liabilities — Mishnah Maasrot 1:1, 1:3, 2:4, 4:5-6; korach.the_tithe by CALL); the exam\'s person the one who eats a casual snack before the pile is smoothed — EXEMPT (Maasrot 1:5)')
        return out("the liabilities (14:22) — the yield of your seed, the field, year by year: food, guarded, grown from the ground (the Sifrei 105:1-19; Mishnah Maasrot 1:1 — KO.the_tithe by CALL), the thresholds the pile smoothed (KO 'thresholds'): the one who eats a casual snack before the pile is smoothed exempt", ['exempt'])
