    del P_[:]
    ask = case['ask']
    if ask == 'the_table':
        ink('14:1-29', 'twenty-nine verses, twenty-nine rows — one per verse; THE CHAPTER IS LAW FROM ITS FIRST WORD TO ITS LAST — no imperative, no first person, no narrative verb, the one "and when" at 14:24; the register plural for the food laws, singular for the tithe, 14:21 both %s' % (([v for v, (p, s) in NUM.items() if p and not s], [v for v, (p, s) in NUM.items() if s and not p], [v for v, (p, s) in NUM.items() if p and s]),))
